                kind: "starts" | "waits_for" | "checks" | "emits" | "goal" | "exits_on" | "fills" | "adds_to" | "removes_from" | "enters" | "exits" | "enrolls" | "stops" | "tags" | "untags" | "pushes" | "calls" | "posts" | "requests" | "records";
