            /** @description The smallest max-snippet set */
            max_snippet?: number;
            /** @description robots or bingbot says noarchive or nocache. */
            noarchive?: boolean;
            /** @description Elements marked data-nosnippet. */
            data_nosnippet?: number;
            /** @description h2 and h3 headings. */
